-- Launch prep (22 Nov 2026). Additive and safe to run twice.
--  * Quiz Site Settings > Terms & Conditions: pop-up title, agree button, text (defaults = the launch T&C)
--  * Quiz Site Settings > Leaderboard: "Show Daily / Weekly / Monthly tabs" (off = All Time only)
--  * Quiz Settings > Game Timers & Scoring > Speed bonus: on/off and tiers
-- Generated from a Drizzle snapshot diff, then made repeatable. The old login_terms_url and
-- login_privacy_url columns are no longer used; they are left in place (nothing is dropped).

CREATE TABLE IF NOT EXISTS "quiz_settings_scoring_bonus_tiers" (
	"_order" integer NOT NULL,
	"_parent_id" integer NOT NULL,
	"id" varchar PRIMARY KEY NOT NULL,
	"min_percent_left" numeric,
	"bonus" numeric
);

ALTER TABLE "quiz_settings" ADD COLUMN IF NOT EXISTS "scoring_speed_bonus" boolean DEFAULT true;

ALTER TABLE "quiz_site_settings" ADD COLUMN IF NOT EXISTS "leaderboard_show_period_tabs" boolean DEFAULT false;

ALTER TABLE "quiz_site_settings" ADD COLUMN IF NOT EXISTS "terms_title" varchar DEFAULT 'Terms & Conditions';

ALTER TABLE "quiz_site_settings" ADD COLUMN IF NOT EXISTS "terms_agree_button" varchar DEFAULT 'I Agree';

ALTER TABLE "quiz_site_settings" ADD COLUMN IF NOT EXISTS "terms_content" jsonb DEFAULT '{"root":{"direction":"ltr","format":"","indent":0,"version":1,"type":"root","children":[{"direction":"ltr","format":"","indent":0,"version":1,"type":"paragraph","textFormat":0,"textStyle":"","children":[{"type":"text","text":"ChenZ – Daily Trivia is an online trivia contest organised by Super Chennai. By participating in ChenZ – Daily Trivia, participants agree to abide by the following Terms & Conditions.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"heading","tag":"h3","children":[{"type":"text","text":"1. Contest Format","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"list","listType":"bullet","tag":"ul","start":1,"children":[{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":1,"children":[{"type":"text","text":"Three trivia questions will be published every day at 8:00 AM.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":2,"children":[{"type":"text","text":"Each question will have a time limit of 20 seconds.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":3,"children":[{"type":"text","text":"Participants must submit their answers within the allotted time.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":4,"children":[{"type":"text","text":"The quiz will be conducted through the ChenZ – Daily Trivia platform on the Super Chennai website or other designated digital platforms.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":5,"children":[{"type":"text","text":"The organisers reserve the right to determine the format, content and schedule of the contest.","format":0,"style":"","mode":"normal","detail":0,"version":1}]}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"heading","tag":"h3","children":[{"type":"text","text":"2. Scoring","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"list","listType":"bullet","tag":"ul","start":1,"children":[{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":1,"children":[{"type":"text","text":"Points will be awarded based on the correctness of answers and response time.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":2,"children":[{"type":"text","text":"Participants who answer correctly in the shortest time will earn higher points.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":3,"children":[{"type":"text","text":"Incorrect or unanswered questions will receive zero points.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":4,"children":[{"type":"text","text":"Scores from all three questions will contribute to the participant’s daily score.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":5,"children":[{"type":"text","text":"Daily scores will also contribute towards the cumulative 90-day leaderboard.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":6,"children":[{"type":"text","text":"The scoring system implemented on the platform will determine the points awarded.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":7,"children":[{"type":"text","text":"Platform-recorded scores, subject to verification, will be considered for winner* determination and leaderboard rankings.","format":0,"style":"","mode":"normal","detail":0,"version":1}]}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"heading","tag":"h3","children":[{"type":"text","text":"3. Daily Winners & Gift Vouchers","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"list","listType":"bullet","tag":"ul","start":1,"children":[{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":1,"children":[{"type":"text","text":"Every day, participants who answer all three questions correctly in the fastest time will be eligible to win* daily gift vouchers.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":2,"children":[{"type":"text","text":"The three participants who complete all three questions correctly with the fastest overall response times will be declared the daily winners.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":3,"children":[{"type":"text","text":"Winners will be determined based on the time taken to correctly answer all three questions, subject to verification.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"type":"listitem","value":4,"children":[{"type":"text","text":"Participants who do not answer all three questions correctly will not be eligible for the daily gift vouchers.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"direction":"ltr","format":"","indent":0,"version":1,"